    <div class="terminal-tabs" id="term-tabs">
      <div class="terminal-tab active" data-sess="main">main</div>
      <div class="terminal-tab" id="term-new-session-btn" style="padding:6px 10px;color:var(--text-3)">＋</div>
    </div>
