const alt = j.alternative ? `<div style="font-size:11px;color:var(--accent-text);margin-top:6px">${escHtml(j.alternative)}</div>` : '';
res.innerHTML = `<div style="color:var(--yellow)">⚠️ ${escHtml(j.error||'Setup required')}</div>${setup}${alt}`;
