        <div style="font-size:11px;color:var(--text-3)">Runs: ${l.run_count||0} · Next: ${l.next_run?new Date(l.next_run).toLocaleTimeString():'—'}${l.status==='paused'?' · <span style="color:var(--warning)">PAUSED</span>':''}</div>
